import {SPECIES,ELEMENTS,ITEMS} from './data.js';
import {HABITATS,habitatFor,habitatName,ecologyStatus} from './ecology.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const portrait=(id,size=120)=>`<canvas width="${size*2}" height="${size*2}" style="width:${size}px;height:${size}px" data-species="${id}" aria-hidden="true"></canvas>`;
const reward=h=>Object.entries(h.reward).map(([id,n])=>`${ITEMS[id].name} × ${n}`).join(' · ');
export function ecologyMarkup(game){
 const done=HABITATS.filter(h=>ecologyStatus(game,h.family).claimed).length;
 return `<section class="ecology-cover"><span class="eyebrow">洛珈博士的群岛调查 · ${done} / 4 份记录</span><h3>放轻脚步，<br>世界会露出一点秘密。</h3><p>四封来自野外的观察邀请。去指定分区寻找「潮灵踪迹」，读懂线索，和藏在风、光与冰雪里的伙伴相遇。</p><div class="ecology-legend"><span>① 读懂踪迹</span><span>② 与家族缔约</span><span>③ 认识最终形态</span></div></section><div class="ecology-grid">${HABITATS.map(h=>{const s=ecologyStatus(game,h.family),species=SPECIES[h.family];return `<article class="ecology-card" style="--ecology-color:${ELEMENTS[species.element].color}"><div class="ecology-art">${portrait(s.grown?h.family+'_3':h.family)}<span>${s.claimed?'✧ 记录已交换':s.ready?'✦ 可以交换记录':s.steps+' / 3 项观察'}</span></div><div class="ecology-copy"><small>${esc(habitatName(h))}</small><h3>${species.name}家族</h3><p>${esc(h.intro)}</p><button class="text-button" data-ecology-family="${h.family}">翻开「${h.title}」 →</button></div></article>`;}).join('')}</div><p class="section-note">踪迹会留在原地，错过缔约也可再来。图鉴与驿站中的成长记录都算数；每份完成的调查只赠送一次补给。</p><button id="ecology-dex" class="secondary">返回潮灵图鉴</button>`;
}
export function ecologyEntryMarkup(game,family){
 const h=habitatFor(family),s=ecologyStatus(game,family),here=game.region===h.region&&game.place==='route'&&game.routeSector===h.sector;
 return `<div class="ecology-entry-heading" style="--ecology-color:${ELEMENTS[SPECIES[family].element].color}">${portrait(s.grown?family+'_3':family,144)}<div><span class="eyebrow">${esc(h.observer)}的观察邀请</span><h3>${h.title}</h3><p>${esc(habitatName(h))}</p></div></div><blockquote class="ecology-note">${esc(h.intro)}</blockquote><section class="ecology-clue"><small>野外线索</small><p>${esc(h.clue)}</p></section><div class="ecology-checks">${[[s.traced,'读懂踪迹','前往栖息地，回应环境线索。'],[s.caught,'结识这个家族','正常对战后使用星约石缔约。'],[s.grown,'认识最终成长形态','16、32 级成长；已缔约的最终形态也会记入。']].map(([ok,title,detail])=>`<div class="${ok?'done':''}"><span>${ok?'✓':'○'}</span><div><strong>${title}</strong><p>${detail}</p></div></div>`).join('')}</div>${s.complete?`<blockquote class="ecology-note completed">${esc(h.ending)}</blockquote>`:''}<div class="ecology-reward"><div><small>${s.claimed?'记录已交换 · 补给已收好':'完整调查的答谢'}</small><p>${reward(h)}</p></div><button id="ecology-claim" class="primary" ${s.ready?'':'disabled'}>${s.claimed?'已经领取':'交换记录'}</button></div><div class="card-actions"><button id="ecology-route" class="secondary">${here?'在随身航图找到踪迹':'打开群岛航图'}</button><button id="ecology-index" class="text-button">返回生态手帐</button></div>`;
}
export function ecologyTraceMarkup(game,family){
 const h=habitatFor(family),s=ecologyStatus(game,family);
 return `<div class="ecology-trace-title"><span class="eyebrow">${esc(habitatName(h))} · 潮灵踪迹</span><h3>${h.title}</h3></div><section class="ecology-clue"><p>${esc(h.clue)}</p></section><p id="ecology-feedback" class="ecology-feedback" role="status">${s.traced?'你已经认识了这处踪迹。再回应一次，等它出来见面吧。':'放轻脚步，想想怎样回应。'}</p><div class="ecology-choices">${h.choices.map((c,i)=>`<button data-ecology-choice="${i}"><span>0${i+1}</span>${esc(c)}</button>`).join('')}</div><p class="section-note">对方会带来一场野外对战。请先准备好伙伴与星约石。</p><button id="ecology-trace-book" class="text-button">查看这页生态手帐 →</button>`;
}
